    service.add(makeMovie(1));
    service.add(makeMovie(1));

    expect(service.count()).toBe(1);
  });

  it('should remove a movie by id', () => {
    service.add(makeMovie(1));
    service.add(makeMovie(2));

    service.remove(1);

    expect(service.count()).toBe(1);
    expect(service.items()[0].id).toBe(2);
